package cn.zhuatech.aps.controller; import cn.zhuatech.aps.common.ApiResponse; import cn.zhuatech.aps.dto.ApsDto.*; import cn.zhuatech.aps.service.ApsService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('PLANNER','QUALITY','ADMIN')") public class ManufacturingAdminController {private final ApsService aps;public ManufacturingAdminController(ApsService aps){this.aps=aps;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(aps.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkOrderView>> orders(){return ApiResponse.ok(aps.workOrders());}}
